    13→)
    14→
    15→// ReturnTrieLayer returns the representation of a merkle trie when
    16→// provided with the elements of a fixed sized trie and the corresponding depth of
    17→// it.
    18→func ReturnTrieLayer(elements [][32]byte, length uint64) ([][]*[32]byte, error) {
    19→	leaves := elements
    20→
    21→	if len(leaves) == 1 {
    22→		return [][]*[32]byte{{&leaves[0]}}, nil
    23→	}
    24→	hashLayer := leaves
    25→	layers := make([][][32]byte, ssz.Depth(length)+1)
    26→	layers[0] = hashLayer
    27→	var err error
    28→	layers, _, err = MerkleizeTrieLeaves(layers, hashLayer)
    29→	if err != nil {
    30→		return nil, err
    31→	}
    32→	refLayers := make([][]*[32]byte, len(layers))
    33→	for i, val := range layers {
    34→		refLayers[i] = make([]*[32]byte, len(val))
    35→		for j, innerVal := range val {
    36→			newVal := innerVal
    37→			refLayers[i][j] = &newVal
    38→		}
    39→	}
    40→	return refLayers, nil
    41→}
    42→
    43→// ReturnTrieLayerVariable returns the representation of a merkle trie when
    44→// provided with the elements of a variable sized trie and the corresponding depth of
    45→// it.
    46→func ReturnTrieLayerVariable(elements [][32]byte, length uint64) [][]*[32]byte {
    47→	depth := ssz.Depth(length)
    48→	layers := make([][]*[32]byte, depth+1)
    49→	// Return zerohash at depth
    50→	if len(elements) == 0 {
    51→		zerohash := trie.ZeroHashes[depth]
    52→		layers[len(layers)-1] = []*[32]byte{&zerohash}
    53→		return layers
    54→	}
    55→	transformedLeaves := make([]*[32]byte, len(elements))
    56→	for i := range elements {
    57→		arr := elements[i]
    58→		transformedLeaves[i] = &arr
    59→	}
    60→	layers[0] = transformedLeaves
    61→	buffer := bytes.NewBuffer([]byte{})
    62→	buffer.Grow(64)
    63→
    64→	for i := uint8(0); i < depth; i++ {
    65→		layerLen := len(layers[i])
    66→		oddNodeLength := layerLen%2 == 1
    67→		if oddNodeLength {
    68→			zerohash := trie.ZeroHashes[i]
    69→			elements = append(elements, zerohash)
    70→			layerLen++
    71→		}
    72→
    73→		layers[i+1] = make([]*[32]byte, layerLen/2)
    74→		elements = htr.VectorizedSha256(elements)
    75→		for j := range elements {
    76→			layers[i+1][j] = &elements[j]
    77→		}
    78→	}
    79→	return layers
    80→}
    81→
    82→// RecomputeFromLayer recomputes specific branches of a fixed sized trie depending on the provided changed indexes.
    83→func RecomputeFromLayer(changedLeaves [][32]byte, changedIdx []uint64, layer [][]*[32]byte) ([32]byte, [][]*[32]byte, error) {
    84→	hasher := hash.CustomSHA256Hasher()
    85→	for i, idx := range changedIdx {
    86→		layer[0][idx] = &changedLeaves[i]
    87→	}
    88→
    89→	if len(changedIdx) == 0 {
    90→		return *layer[0][0], layer, nil
    91→	}
    92→
    93→	leaves := layer[0]
    94→
    95→	// We need to ensure we recompute indices of the Merkle tree which
    96→	// changed in-between calls to this function. This check adds an offset
    97→	// to the recomputed indices to ensure we do so evenly.
    98→	maxChangedIndex := changedIdx[len(changedIdx)-1]
    99→	if int(maxChangedIndex+2) == len(leaves) && maxChangedIndex%2 != 0 {
   100→		changedIdx = append(changedIdx, maxChangedIndex+1)
   101→	}
   102→
   103→	root := *layer[0][0]
   104→
   105→	for _, idx := range changedIdx {
   106→		ii, err := math.Int(idx)
   107→		if err != nil {
   108→			return [32]byte{}, nil, err
   109→		}
   110→		root, layer, err = recomputeRootFromLayer(ii, layer, leaves, hasher)
   111→		if err != nil {
   112→			return [32]byte{}, nil, err
   113→		}
   114→	}
   115→	return root, layer, nil
   116→}
   117→
   118→// RecomputeFromLayerVariable recomputes specific branches of a variable sized trie depending on the provided changed indexes.
   119→func RecomputeFromLayerVariable(changedLeaves [][32]byte, changedIdx []uint64, layer [][]*[32]byte) ([32]byte, [][]*[32]byte, error) {
   120→	hasher := hash.CustomSHA256Hasher()
   121→	if len(changedIdx) == 0 {
   122→		return *layer[0][0], layer, nil
   123→	}
   124→	root := *layer[len(layer)-1][0]
   125→
   126→	for i, idx := range changedIdx {
   127→		ii, err := math.Int(idx)
   128→		if err != nil {
   129→			return [32]byte{}, nil, err
   130→		}
   131→		root, layer, err = recomputeRootFromLayerVariable(ii, changedLeaves[i], layer, hasher)
   132→		if err != nil {
   133→			return [32]byte{}, nil, err
   134→		}
   135→	}
   136→	return root, layer, nil
   137→}
   138→
   139→// this method assumes that the provided trie already has all its elements included
   140→// in the base depth.
   141→func recomputeRootFromLayer(idx int, layers [][]*[32]byte, chunks []*[32]byte,
   142→	hasher func([]byte) [32]byte) ([32]byte, [][]*[32]byte, error) {
   143→	root := *chunks[idx]
   144→	layers[0] = chunks
   145→	// The merkle tree structure looks as follows:
   146→	// [[r1, r2, r3, r4], [parent1, parent2], [root]]
   147→	// Using information about the index which changed, idx, we recompute
   148→	// only its branch up the tree.
   149→	currentIndex := idx
   150→	// Allocate only once.
   151→	var combinedChunks [64]byte
   152→	for i := 0; i < len(layers)-1; i++ {
   153→		isLeft := currentIndex%2 == 0
   154→		neighborIdx := currentIndex ^ 1
   155→
   156→		var neighbor [32]byte
   157→		if layers[i] != nil && len(layers[i]) != 0 && neighborIdx < len(layers[i]) {
   158→			neighbor = *layers[i][neighborIdx]
   159→		}
   160→		if isLeft {
   161→			copy(combinedChunks[:32], root[:])
   162→			copy(combinedChunks[32:], neighbor[:])
   163→		} else {
   164→			copy(combinedChunks[:32], neighbor[:])
   165→			copy(combinedChunks[32:], root[:])
   166→		}
   167→
   168→		parentHash := hasher(combinedChunks[:])
   169→		root = parentHash
   170→
   171→		parentIdx := currentIndex / 2
   172→		// Update the cached layers at the parent index.
   173→		rootVal := root
   174→		if len(layers[i+1]) == 0 {
   175→			layers[i+1] = append(layers[i+1], &rootVal)
   176→		} else {
   177→			layers[i+1][parentIdx] = &rootVal
   178→		}
   179→		currentIndex = parentIdx
   180→	}
   181→	// If there is only a single leaf, we return it (the identity element).
   182→	if len(layers[0]) == 1 {
   183→		return *layers[0][0], layers, nil
   184→	}
   185→	return root, layers, nil
   186→}
   187→
   188→// this method assumes that the base branch does not consist of all leaves of the
   189→// trie. Instead missing leaves are assumed to be zerohashes, following the structure
   190→// of a sparse merkle trie.
   191→func recomputeRootFromLayerVariable(idx int, item [32]byte, layers [][]*[32]byte,
   192→	hasher func([]byte) [32]byte) ([32]byte, [][]*[32]byte, error) {
   193→	for idx >= len(layers[0]) {
   194→		zerohash := trie.ZeroHashes[0]
   195→		layers[0] = append(layers[0], &zerohash)
   196→	}
   197→	layers[0][idx] = &item
   198→
   199→	currentIndex := idx
   200→	root := item
   201→	// Allocate only once.
   202→	var neighbor [32]byte
   203→	var combinedChunks [64]byte
   204→
   205→	for i := 0; i < len(layers)-1; i++ {
   206→		isLeft := currentIndex%2 == 0
   207→		neighborIdx := currentIndex ^ 1
   208→
   209→		if neighborIdx >= len(layers[i]) {
   210→			neighbor = trie.ZeroHashes[i]
   211→		} else {
   212→			neighbor = *layers[i][neighborIdx]
   213→		}
   214→		if isLeft {
   215→			copy(combinedChunks[:32], root[:])
   216→			copy(combinedChunks[32:], neighbor[:])
   217→		} else {
   218→			copy(combinedChunks[:32], neighbor[:])
   219→			copy(combinedChunks[32:], root[:])
   220→		}
   221→
   222→		parentHash := hasher(combinedChunks[:])
   223→		root = parentHash
   224→
   225→		parentIdx := currentIndex / 2
   226→		if len(layers[i+1]) == 0 || parentIdx >= len(layers[i+1]) {
   227→			newItem := root
   228→			layers[i+1] = append(layers[i+1], &newItem)
   229→		} else {
   230→			newItem := root
   231→			layers[i+1][parentIdx] = &newItem
   232→		}
   233→		currentIndex = parentIdx
   234→	}
   235→	return root, layers, nil
   236→}
   237→
   238→// AddInMixin describes a method from which a length mixin is added to the
   239→// provided root.
   240→func AddInMixin(root [32]byte, length uint64) ([32]byte, error) {
   241→	rootBuf := new(bytes.Buffer)
   242→	if err := binary.Write(rootBuf, binary.LittleEndian, length); err != nil {
   243→		return [32]byte{}, errors.Wrap(err, "could not marshal eth1data votes length")
   244→	}
   245→	// We need to mix in the length of the slice.
   246→	rootBufRoot := make([]byte, 32)
   247→	copy(rootBufRoot, rootBuf.Bytes())
   248→	return ssz.MixInLength(root, rootBufRoot), nil
   249→}
   250→
   251→// Merkleize 32-byte leaves into a Merkle trie for its adequate depth, returning
   252→// the resulting layers of the trie based on the appropriate depth. This function
   253→// pads the leaves to a length of a multiple of 32.
   254→func Merkleize(leaves [][]byte) [][][]byte {
   255→	hashFunc := hash.CustomSHA256Hasher()
   256→	layers := make([][][]byte, ssz.Depth(uint64(len(leaves)))+1)
   257→	for len(leaves)%32 != 0 {
   258→		leaves = append(leaves, make([]byte, 32))
   259→	}
   260→	currentLayer := leaves
   261→	layers[0] = currentLayer
   262→
   263→	// We keep track of the hash layers of a Merkle trie until we reach
   264→	// the top layer of length 1, which contains the single root element.
   265→	//        [Root]      -> Top layer has length 1.
   266→	//    [E]       [F]   -> This layer has length 2.
   267→	// [A]  [B]  [C]  [D] -> The bottom layer has length 4 (needs to be a power of two).
   268→	i := 1
   269→	for len(currentLayer) > 1 && i < len(layers) {
   270→		layer := make([][]byte, 0)
   271→		for i := 0; i < len(currentLayer); i += 2 {
   272→			hashedChunk := hashFunc(append(currentLayer[i], currentLayer[i+1]...))
   273→			layer = append(layer, hashedChunk[:])
   274→		}
   275→		currentLayer = layer
   276→		layers[i] = currentLayer
   277→		i++
   278→	}
   279→	return layers
   280→}
   281→
   282→// MerkleizeTrieLeaves merkleize the trie leaves.
   283→func MerkleizeTrieLeaves(layers [][][32]byte, hashLayer [][32]byte) ([][][32]byte, [][32]byte, error) {
   284→	// We keep track of the hash layers of a Merkle trie until we reach
   285→	// the top layer of length 1, which contains the single root element.
   286→	//        [Root]      -> Top layer has length 1.
   287→	//    [E]       [F]   -> This layer has length 2.
   288→	// [A]  [B]  [C]  [D] -> The bottom layer has length 4 (needs to be a power of two).
   289→	i := 1
   290→	chunkBuffer := bytes.NewBuffer([]byte{})
   291→	chunkBuffer.Grow(64)
   292→	for len(hashLayer) > 1 && i < len(layers) {
   293→		if !math.IsPowerOf2(uint64(len(hashLayer))) {
   294→			return nil, nil, errors.Errorf("hash layer is a non power of 2: %d", len(hashLayer))
   295→		}
   296→		hashLayer = htr.VectorizedSha256(hashLayer)
   297→		layers[i] = hashLayer
   298→		i++
   299→	}
   300→	return layers, hashLayer, nil
   301→}
   302→

