package stateutil

import (
	"bytes"
	"encoding/binary"

	"github.com/OffchainLabs/prysm/v6/container/trie"
	"github.com/OffchainLabs/prysm/v6/crypto/hash"
	"github.com/OffchainLabs/prysm/v6/crypto/hash/htr"
