func ReturnTrieLayerVariable(elements [][32]byte, length uint64) [][]*[32]byte {
	depth := ssz.Depth(length)
	layers := make([][]*[32]byte, depth+1)
	if len(elements) == 0 {
		zerohash := trie.ZeroHashes[depth]
		layers[len(layers)-1] = []*[32]byte{&zerohash}
